  ('rate_emergency_fuel', 'บริการเติมน้ำมัน', 'การให้ความช่วยเหลือกรณีรถน้ำมันหมดระหว่างการเดินทาง โดยนำน้ำมันเชื้อเพลิงไปเติมในปริมาณที่เพียงพอ เพื่อให้รถสามารถเดินทางไปยังสถานีบริการน้ำมันที่ใกล้ที่สุดได้อย่างปลอดภัย', 100, 'emergency_assistance', true),
  ('rate_emergency_battery', 'บริการเปลี่ยนแบตเตอรี่', 'การช่วยเหลือรถที่แบตเตอรี่หมดหรือขัดข้อง โดยการพ่วงแบตเตอรี่ (Jump Start) หรือเปลี่ยนแบตเตอรี่ใหม่ตามความเหมาะสม เพื่อให้รถสามารถสตาร์ตและใช้งานได้', 100, 'emergency_assistance', true),
  ('rate_emergency_tire', 'บริการเปลี่ยนยาง', 'การช่วยเหลือผู้ใช้รถที่ยางรั่ว ยางแตก หรือไม่สามารถใช้งานได้ โดยเปลี่ยนเป็นยางอะไหล่หรือดำเนินการเบื้องต้นเพื่อให้รถสามารถเดินทางต่อไปได้อย่างปลอดภัย', 50, 'emergency_assistance', true),
  ('rate_rescue_water', 'บริการกู้รถตกน้ำ', 'การกู้และนำรถที่ตกลงในแหล่งน้ำ เช่น แม่น้ำ คลอง บึง หรือสระ ขึ้นสู่พื้นดินอย่างปลอดภัย โดยใช้อุปกรณ์และรถกู้เฉพาะทาง', 250, 'vehicle_rescue', true),
  ('rate_rescue_lift', 'บริการยกรถ', 'การใช้รถยกหรืออุปกรณ์เฉพาะทางในการยกเคลื่อนย้ายรถที่ไม่สามารถเคลื่อนที่ได้ด้วยตนเองหรืออยู่ในสภาพที่ต้องยกขึ้นก่อนเคลื่อนย้าย', 150, 'vehicle_rescue', true),
  ('rate_rescue_tow', 'บริการลากรถ', 'การเคลื่อนย้ายรถที่เสีย ขัดข้อง หรือประสบอุบัติเหตุ โดยใช้รถลากจูงนำรถไปยังจุดหมายที่กำหนด เช่น อู่ซ่อม ศูนย์บริการ หรือสถานที่ปลอดภัย', 150, 'vehicle_rescue', true),
  ('rate_rescue_suspect', 'บริการลากรถผู้ต้องหา (กรณีตำรวจจับกุม)', 'การประสานงานร่วมระหว่างเจ้าหน้าที่ตำรวจและ DOT ในการเข้ายกลากยานพาหนะของผู้ต้องหาในคดีต่างๆ ไปยังสถานที่จัดเก็บของทางราชการทันทีหลังการจับกุม เพื่อความปลอดภัยของทรัพย์สินและไม่กีดขวางการจราจร', 200, 'vehicle_rescue', true),
